const it = {};

it.gizmo = this.getObjectByName('Gizmo');
it.arContent = this.getObjectByName('ARContent');
it.target = it.gizmo.material.map;
it.obj = this;

this.imageTarget = it;

// Videos que se reproducen juntos al detectar el marcador y se pausan al perderlo
const VIDEOS = ['dog', 'woody'];

let visible = false;
let esperandoToque = false;

function getVideos() {
	return VIDEOS.map((name) => player.getAssetByType('videos', name)).filter(Boolean);
}

// Espera a que el video tenga datos suficientes para arrancar sin trabarse
function listo(v) {
	const el = v.video;
	if (el.readyState >= 3) return Promise.resolve();
	return new Promise((resolve) => {
		const ok = () => { el.removeEventListener('canplay', ok); resolve(); };
		el.addEventListener('canplay', ok);
		setTimeout(ok, 3000); // por si la red está lenta, no se queda esperando
	});
}

// Arranca todos los videos en el mismo instante
function reproducirTodos() {
	const videos = getVideos();
	Promise.all(videos.map(listo)).then(() => {
		if (!visible) return; // la tarjeta se perdió mientras cargaban
		videos.forEach((v) => {
			const p = v.video.play();
			if (p && p.catch) p.catch(() => {
				// El navegador bloqueó el sonido: se reproduce en silencio
				// y el audio se activa con el primer toque en la pantalla
				v.video.muted = true;
				v.video.play().catch(() => {});
				pedirToque();
			});
		});
	});
}

function pedirToque() {
	if (esperandoToque) return;
	esperandoToque = true;
	const activar = () => {
		document.removeEventListener('pointerdown', activar);
		document.removeEventListener('touchend', activar);
		esperandoToque = false;
		getVideos().forEach((v) => {
			v.video.muted = false;
			if (visible) v.video.play().catch(() => {});
		});
	};
	document.addEventListener('pointerdown', activar);
	document.addEventListener('touchend', activar);
}

this.imageTarget.onFound = function() {
	console.log('Image target found:', it);
	visible = true;
	reproducirTodos();
}
this.imageTarget.onLost = function() {
	console.log('Image target lost:', it);
	visible = false;
	getVideos().forEach((v) => v.pause());
}

function init() {
	player.imageTargets.push(this.imageTarget);
	// Precarga los videos desde el inicio para que estén listos al detectar la tarjeta
	getVideos().forEach((v) => {
		v.video.preload = 'auto';
		v.video.setAttribute('playsinline', '');
		v.video.setAttribute('webkit-playsinline', '');
		v.video.load();
	});
}

