const url = 'https://video-eight-xi.vercel.app/assets/dog.mp4';
const name = 'dog';
const chromaMaterial = new THREE.ShaderMaterial({
    uniforms: {
        map: {
            value: null
        },
        keyColor: {
            value: new THREE.Vector3(0, 255, 0)
        },
        threshold: {
            value: 0.6
        },
        smoothness: {
            value: 0.5
        }
    },

    vertexShader: `
        varying vec2 vUv;

        void main() {
            vUv = uv;

            gl_Position = projectionMatrix *
                          modelViewMatrix *
                          vec4(position, 1.0);
        }
    `,

    fragmentShader: `
        uniform sampler2D map;
        uniform vec3 keyColor;
        uniform float threshold;
        uniform float smoothness;

        varying vec2 vUv;

        void main() {
            vec4 color = texture2D(map, vUv);

            vec3 chromaColor = keyColor / 255.0;

            float colorDistance = distance(
                color.rgb,
                chromaColor
            );

            float alpha = smoothstep(
                threshold,
                threshold + smoothness,
                colorDistance
            );

            gl_FragColor = vec4(
                color.rgb,
                color.a * alpha
            );

            if (gl_FragColor.a < 0.01) {
                discard;
            }
        }
    `,

    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide
});

this.material = chromaMaterial;

const video = player.loadVideo(name, url, (video) => {
    chromaMaterial.uniforms.map.value = video.texture;
    video.setLoop(true);
    video.setVolume(1);

	if (player.isEditor) {video.play(); }
});

