// ===== VIDEO 2: WOODY =====
// El video va guardado dentro de este JSON (userData.videoBase64 del objeto), así que
// funciona sin subirlo a ningún lado. Si prefieres cargarlo desde Vercel, pega aquí
// el enlace (ej: 'https://video-eight-xi.vercel.app/assets/woody.mp4').
const URL_EXTERNA = '';
const name = 'woody';

// true = quita el fondo verde (como el video del perro). false = video normal.
const CHROMA = true;

const self = this;
const ANCHO = 0.9; // ancho del video sobre la tarjeta; el alto se calcula solo
// Parte vacía (fondo verde) debajo de los pies en el video: 0.25 = 25 %.
// Se usa para bajar el plano y que Woody quede parado sobre la tarjeta.
const ESPACIO_PIES = 0.25;

let material;
if (CHROMA) {
    material = new THREE.ShaderMaterial({
        uniforms: {
            map: { value: null },
            keyColor: { value: new THREE.Vector3(0, 255, 0) },
            threshold: { value: 0.6 },
            smoothness: { value: 0.5 }
        },
        vertexShader: `
            varying vec2 vUv;
            void main() {
                vUv = uv;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `,
        fragmentShader: `
            uniform sampler2D map;
            uniform vec3 keyColor;
            uniform float threshold;
            uniform float smoothness;
            varying vec2 vUv;
            void main() {
                vec4 color = texture2D(map, vUv);
                float alpha = smoothstep(threshold, threshold + smoothness, distance(color.rgb, keyColor / 255.0));
                gl_FragColor = vec4(color.rgb, color.a * alpha);
                if (gl_FragColor.a < 0.01) discard;
            }
        `,
        transparent: true,
        depthWrite: false,
        side: THREE.DoubleSide
    });
} else {
    material = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide });
}
this.material = material;

function videoUrl() {
    if (URL_EXTERNA) return URL_EXTERNA;
    const bin = atob(self.userData.videoBase64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return URL.createObjectURL(new Blob([bytes], { type: self.userData.videoType || 'video/mp4' }));
}
const url = videoUrl();

const video = player.loadVideo(name, url, (video) => {
    video.texture.colorSpace = THREE.SRGBColorSpace;
    if (CHROMA) material.uniforms.map.value = video.texture;
    else { material.map = video.texture; material.needsUpdate = true; }
    video.setLoop(true);
    video.setVolume(1);

    // Ajusta el plano a la proporción real del video, apoyado sobre la tarjeta
    video.video.addEventListener('loadedmetadata', () => {
        const w = video.video.videoWidth, h = video.video.videoHeight;
        if (!w || !h) return;
        self.scale.set(ANCHO, ANCHO * h / w, 1);
        self.position.y = self.scale.y / 2 - self.scale.y * ESPACIO_PIES;
    });

    if (player.isEditor) { video.play(); }
});
